int checkpal(char word[],int position)
{
    int len;
    len=strlen(word)-(position+1);
    if (word[position]==word[len])
    {
        if((position+1)==len||(position==len))
        {
            return 1;
        }
        checkpal(word,position+1);
    }
    else return 0;
}

